import math

ALPHABET_SIZE = 26
GROUP_SIZE = 5


def _check_coprime(a):
    if math.gcd(a, ALPHABET_SIZE) != 1:
        raise ValueError("a and m must be coprime.")


def _modular_inverse(a):
    for x in range(ALPHABET_SIZE):
        if (a * x) % ALPHABET_SIZE == 1:
            return x
    raise ValueError("a and m must be coprime.")


def _encrypt_char(char, a, b):
    index = ord(char) - ord("a")
    return chr((a * index + b) % ALPHABET_SIZE + ord("a"))


def _decrypt_char(char, a_inv, b):
    index = ord(char) - ord("a")
    return chr((a_inv * (index - b)) % ALPHABET_SIZE + ord("a"))


def encode(plain_text, a, b):
    _check_coprime(a)
    ciphertext = []
    for char in plain_text.lower():
        if char.isalpha():
            ciphertext.append(_encrypt_char(char, a, b))
        elif char.isdigit():
            ciphertext.append(char)
    return " ".join(
        "".join(ciphertext)[i : i + GROUP_SIZE]
        for i in range(0, len(ciphertext), GROUP_SIZE)
    )


def decode(ciphered_text, a, b):
    _check_coprime(a)
    a_inv = _modular_inverse(a)
    plaintext = []
    for char in ciphered_text:
        if char.isalpha():
            plaintext.append(_decrypt_char(char, a_inv, b))
        elif char.isdigit():
            plaintext.append(char)
    return "".join(plaintext)

